const HASH_LENGTH = 2;
const IMAGE_EXT = ".jpg";
const TARGETS = JSON.parse("{\"a\": {\"dir\": \"a\", \"slots\": 256, \"ext\": \".jpeg\", \"label\": \"avatar\"}, \"gif\": {\"dir\": \"gif\", \"slots\": 256, \"ext\": \".gif\", \"label\": \"gif\"}, \"h\": {\"dir\": \"h\", \"slots\": 256, \"ext\": \".jpg\", \"label\": \"horizontal\"}, \"v\": {\"dir\": \"v\", \"slots\": 256, \"ext\": \".jpg\", \"label\": \"vertical\"}}");

